# Parse JUnit generated by BuildCharts test output for a sample.
param(
  [string]$TestOutputDirectory
)

$ErrorActionPreference = "Stop"
$reports = @(Get-ChildItem -Path $TestOutputDirectory -Recurse -Filter junit.xml -File)
if ($reports.Count -eq 0) {
  throw "No junit.xml file found under $TestOutputDirectory"
}

$results = @(
  foreach ($report in $reports) {
    [xml]$junit = [System.IO.File]::ReadAllText($report.FullName)
    $junit.SelectNodes("//*[local-name()='testcase']")
  }
)
if ($results.Count -eq 0) {
  throw "No test cases found under $TestOutputDirectory"
}

$failed = @($results | Where-Object { $_.SelectSingleNode("*[local-name()='failure' or local-name()='error']") })
$skipped = @($results | Where-Object { $_.SelectSingleNode("*[local-name()='skipped']") })
Write-Host ("Total={0} Passed={1} Failed={2} Skipped={3}" -f $results.Count, ($results.Count - $failed.Count - $skipped.Count), $failed.Count, $skipped.Count)
if ($failed.Count -gt 0) {
  throw ("Failed tests: " + ($failed.name -join ", "))
}
